function walk(dirs) {
  let x = 0, y = 0
  for (const d of dirs) {
    if (d === "east") x += 1
    if (d === "west") x -= 1
    if (d === "south") y += 1
    if (d === "north") y -= 1
  }
  return { x, y }
}
const p = walk(["east", "east", "east", "south", "south"])
console.log(p.x + "," + p.y)
module.exports = { walk }
